private static boolean canTravelMazeHelper(int[] start, int[] end, int[][] paths, boolean[][] visited, boolean[][] path) {
    if (path[start[0]][start[1]]) {
        return false;
    }
    if (start[0] == end[0] && start[1] == end[1]) {
        return true;
    }
    path[start[0]][start[1]] = true;
    for (int[] pathMove : paths) {
        int nextX = start[0] + pathMove[0];
        int nextY = start[1] + pathMove[1];
        if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
            if (canTravelMazeHelper(nextX, nextY, paths, visited, path)) {
                return true;
            }
        }
    }
    return false;
