import java.util.HashMap;
import java.util.Map;

public class TwoSumSolution {

    /**
     * Finds two numbers in the given array that add up to the target sum.
     *
     * @param nums   The array of integers.
     * @param target The target sum.
     * @return An array of two integers representing the indices of the two numbers.
     *         If no such indices exist, returns an array with two -1 values.
     */
    public static int[] findTwoSum(int[] nums, int target) {
        Map<Integer, Integer> numMap = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (numMap.containsKey(complement)) {
                return new int[]{numMap.get(complement), i};
            }
            numMap.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }

    public static void main(String[] args) {
        // Example usage
        int[] nums = {2, 7, 11, 15};
        int target = 9;
        int[] result = findTwoSum(nums, target);
        System.out.println("Indices of the two numbers that add up to the target sum: " + result[0] + " and " + result[1]);
    }
}
