    public boolean canArrange(int[] arr, int k) {
        if (arr.length % 2 != 0) {
            return false;
        }

        int[] remainderCount = new int[k];
        for (int num : arr) {
            remainderCount[num % k]++;
        }

        for (int remainder = 0; remainder < k; remainder++) {
            if (remainderCount[remainder] > remainderCount[k - remainder]) {
                return false;
            }
        }

        return true;
    }

