import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int maxUniqueSplit(String s) {
        Set<String> seen = new HashSet<>();
        return explore(s, seen) + 1;
    }

    private int explore(String s, Set<String> seen) {
        if (s.length() == 0) {
            return 0;
        }
        int maxUnique = 1;
        for (int i = 1; i <= s.length(); i++) {
            String prefix = s.substring(0, i);
            if (!seen.contains(prefix)) {
                seen.add(prefix);
                maxUnique = Math.max(maxUnique, explore(s.substring(i), seen) + 1);
                seen.remove(prefix);
            }
        }
        return maxUnique;
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        System.out.println(sol.maxUniqueSplit("ababccc")); // Output: 5
        System.out.println(sol.maxUniqueSplit("abcd")); // Output: 1
        System.out.println(sol.maxUniqueSplit("aaabcd")); // Output: 3
        System.out.println(sol.maxUniqueSplit("ababac")); // Output: 4
    }
}
