    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        throw new IllegalArgumentException("Invalid matrix dimensions");
    }

    int m = mat.length, n = mat[0].length;
    int ans = 0, maxValue = 0;

    // Search for horizontal lines
    for (int row = 0; row < m; row++) {
        for (int col = 0, count = 1; col < n - 1; col++) {
            if (mat[row][col] == 1 && mat[row][col + 1] == 1) {
                count++;
                maxValue = Math.max(maxValue, count);
            } else {
                count = 1;
            }
        }
    }

    // Search for vertical lines
    for (int col = 0; col < n; col++) {
        for (int row = 0, count = 1; row < m - 1; row++) {
            if (mat[row][col] == 1 && mat[row + 1][col] == 1) {
                count++;
                maxValue = Math.max(maxValue, count);
            } else {
                count = 1;
            }
        }
    }

    // Search for diagonal lines
    for (int d = 0; d < m; d++) {
        for (int i = d, j = 0; i < m - d && j < n; i++, j++) {
            if (mat[i][j] == 1 && mat[i + 1][j + 1] == 1) {
                count++;
                maxValue = Math.max(maxValue, count);
            } else {
                count = 1;
            }
        }
    }

    // Search for anti-diagonal lines
    for (int d = 0; d < m; d++) {
        for (int i = max(d, n - 1 - d), j = 0; i < m && j < n; i++, j++) {
