private static final int CatalanNumber(int n) {
    return (int) (Math.pow(2, n)) * (n + 1) / (n + 2);
}

public static int squarePermutations(int[] A) {
    int length = A.length;
    if (length <= 1) return CatalanNumber(length);

    int count = 0;
    boolean[] taken = new boolean[length];
    int[][] dp = new int[length][length];
    dp[0][0] = 1;
    dp[0][1] = 1;

    for (int i = 1; i < length; i++) {
        for (int j = 0; j <= i; j++) {
            int k = i - j;
            if (k < 0 || (!taken[j] && taken[k] || (taken[j] && !taken[k] && (sq(A[j]) + sq(A[k])) > sq(A[i])) ) {
                dp[i][j] = dp[i - 1][j];
                dp[i][k] = dp[i - 1][k];
            } else {
                dp[i][j] += (k >= 1 && !taken[j] && !taken[k]) ? dp[i - 2][j] : 0;
                dp[i][k] += (j < i - 1 && !taken[j] && !taken[k]) ? dp[i - 2][k - 1] : 0;
            }
        }
        taken[i] = true;
    }

    count = 0;
    for (int i = 0; i < length; i++) {
        count += dp[length - 1][i];
    }

    return count;
}

private static boolean sq(int n) {
    return n * n;
}
