public static int largestRectangleArea(int[] heights) {
    int size = heights.length;
    int[] nse = new int[size]; // NSE for the right side
    int[] lse = new int[size]; // LSE for the left side

    // NSE Initialization
    int maxIndex = size - 1;
    nse[maxIndex] = size;
    for(int i = size - 2; i >= 0; i--) {
        while(maxIndex >= 0 && heights[nse[maxIndex]] >= heights[i]) {
            maxIndex = nse[maxIndex] - 1;
        }
        nse[i] = maxIndex;
    }

    // LSE Initialization
    maxIndex = 0;
    lse[maxIndex] = -1;
    for(int i = 0; i < size; i++) {
        while(maxIndex < size && heights[lse[maxIndex]] >= heights[i]) {
            maxIndex = lse[maxIndex] + 1;
        }
        lse[i] = maxIndex;
    }

    int maxArea = 0;
    for(int i = 0; i < size; i++) {
        int breadth = nse[i] - lse[i] - 1;
        int area = breadth * heights[i];
        maxArea = Math.max(maxArea, area);
    }
    return maxArea;
}
