public static int findSmallestInteger(int n) {
    if (n == 0) return -1; // If n is 0, there can't be any smaller number
    int[] digits = new int[String.valueOf(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    Arrays.sort(digits);

    int smallest = 0, power = 1;
    for (int i = digits.length - 1; i >= 0; i--) {
        smallest += digits[i] * power;
        power *= 10;
    }

    return smallest > n ? -1 : smallest;
}
