public static int findNthUglyNumber(int n) {
    if (n <= 0)
        return 0;

    int ugly = 0;
    int[] factors = {2, 3, 5};

    // List to keep track of the generated ugly numbers
    List<Integer> uglyNumbers = new ArrayList<>();
    uglyNumbers.add(1);

    // Generate the uglier number until we reach the nth ugly number
    for (int i = 1; i < n; i++) {
        ugly = Integer.MAX_VALUE;
        // Get the smallest number possible by multiplying the current_factors
        for (int factor : factors) {
            if (uglyNumbers.get(i - 1) * factor <= uglyNumbers.get(uglyNumbers.size() - 1)) {
                ugly = uglyNumbers.get(i - 1) * factor;
            }
        }

        // Add the generated ugly number to the list
        uglyNumbers.add(ugly);

        // Remove duplicate ugly numbers to avoid considering them multiple times
        for (int multiple = ugly; multiple < uglyNumbers.get(uglyNumbers.size() - 1); multiple += ugly) {
            uglyNumbers.remove(uglyNumbers.size() - 1);
        }
    }

    return uglyNumbers.get(n - 1);
}
